head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getAttribute]<br/>XML Document 또는 XML Element 에서 속성(attribute) 값을 반환합니다.",
    "validation" : [
        "doc(필수) 파라미터로 XML Element 노드를 설정할 수 있어야 합니다.",
        "doc(필수) 파라미터에 XML 문자열을 전달하면 내부적으로 parse() 하여 XML Document 로 변환해야 합니다.",
        "Element 모드: Element 에서 직접 속성값을 조회할 수 있어야 합니다.",
        "속성이 없거나 null 인 경우 빈 문자열을 반환해야 합니다.",
    ]
}

scwin.testDoc = null;
scwin.bookNode = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.testDoc = WebSquare.xml.parse("<book idx='1' category='fiction'><title lang='eng'>Harry Potter</title><price currency='USD'>29.99</price></book>");
    scwin.bookNode = WebSquare.xml.findNode(scwin.testDoc, "book");
};



scwin.btn_getAttribute_2param_onclick = function () {
    let attrName = par_attrName.getValue();

    var result = WebSquare.xml.getAttribute(scwin.bookNode, attrName);

    wf_body_bottom.getObj("scwin").setReturnValue("Element: getAttribute(bookNode, '" + attrName + "')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 : '" + result + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);
}



scwin.btn_getAttribute_string_onclick = function () {
    var xmlStr = "<item type='A' status='active'/>";

    var result = WebSquare.xml.getAttribute(xmlStr, "type");

    wf_body_bottom.getObj("scwin").setReturnValue("XML 문자열 전달: getAttribute(xmlString, 'type')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 : '" + result + "'");
}
